/// <summary>
/// Converts the item price to the priceDiscParameters currency and unit.
/// </summary>
/// <param name = "_inventTableModule">
/// An <c>InventTableModule</c> record buffer.
/// </param>
/// <param name = "_priceDiscDim">
/// The <c>PriceConvertFactory</c> object.
/// </param>
protected void convertPrice(InventTableModule _inventTableModule, InventDim _priceDiscDim)
{
    /// If a product variant is specified in the price discount dimension,
    if (_priceDiscDim.configId)
    {
        InventDim inventDim;

        inventDim.configId = _priceDiscDim.configId;
        inventDim = InventDim::findOrCreate(inventDim);

        /// find the corresponding inventory table module for the distinct product variant.
        var inventDimCombination = InventDimCombination::find(_inventTableModule.ItemId, inventDim.inventDimId);

        var inventModuleTableVariant = InventTableModule::findByProductVariant_AVA
        (
            inventDimCombination.DistinctProductVariant,
            ModuleInventPurchSales::AVARUMSalesForProductVariants
        );

        if (inventModuleTableVariant && inventModuleTableVariant.AVARUMOverrideSettings)
        {
            /// and if the found inventory table module has override settings enabled,
            _inventTableModule.PriceUnit = inventModuleTableVariant.PriceUnit;
        }
    }

    next convertPrice(_inventTableModule, _priceDiscDim);
    // Additional logic can be added here if needed in the future.
}
